import{_ as s,l as o,o as e,c as n,v as t,p as l,x as r,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"数组与随机访问","description":"","frontmatter":{"title":"数组与随机访问","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/array-random-access.md","filePath":"cs/array-random-access.md","lastUpdated":1789023840000}'),m={name:"cs/array-random-access.md"};function p(A,a,_,T,f,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="数组与随机访问" tabindex="-1">数组与随机访问 <a class="header-anchor" href="#数组与随机访问" aria-label="Permalink to &quot;数组与随机访问&quot;">​</a></h1><div class="epigraph"><p>下标到地址是一次乘加；RAM 模型里那是 $O(1)$，前提是元素连续且大小已知。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/adt-cost">上一课</a>把结构写成操作加代价，还没有任何一种布局。<a href="/cs/bit-as-distinction">比特作为区分</a>与<a href="/cs/adt-cost">进制与位权</a>已经能把下标写成整数。<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>按地址读字。<a href="/cs/calling-convention-stack">调用约定与栈</a>里的栈槽其实已经是数组片段。本课不重讲 ADT 合同。缺口是第一种表示：连续元素 + 按下标 \\(O(1)\\) 取。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>集合的「第 \\(i\\) 个」若每次从头数，代价随 \\(i\\) 涨。硬件却已经提供按物理地址的常数时间字访问（cache 命中时）。缺口是把 ADT 的下标映射到地址：\\(\\mathrm{addr}(A[i]) = \\mathrm{base} + i \\times \\mathrm{size}\\)。本课只钉静态长度或长度存在另处的定长数组，不讨论自动扩容——那是摊还课。</p><p>插入到中间要搬移后续元素，最坏 \\(\\Theta(n)\\)。合同必须把「按下标读」和「在中间插入」分开写，不能都叫 \\(O(1)\\)。</p><p><span class="marginnote">RAM 模型假定任意字地址 \\(O(1)\\)。层次存储器下这是命中时的近似；行对齐的顺序扫才吃满空间局部性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>表示：一块连续虚拟地址，元素同宽。读写下标 \\(i\\) 合法当且仅当 \\(0\\le i\\lt n\\)。构造分配 \\(n\\times\\mathrm{size}\\) 字节。随机访问 \\(\\Theta(1)\\) 步；顺序扫 \\(\\Theta(n)\\) 步且对 cache 友好。</p>',9)),(e(),l(h,null,{default:r(()=>[d(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20I%5B%22%E4%B8%8B%E6%A0%87%20i%22%5D%20--%3E%20MUL%5B%22i%20%C3%97%20%E5%85%83%E7%B4%A0%E5%A4%A7%E5%B0%8F%22%5D%0A%20%20MUL%20--%3E%20ADD%5B%22%E5%8A%A0%E5%9F%BA%E5%9D%80%22%5D%0A%20%20ADD%20--%3E%20LD%5B%22%E4%B8%80%E6%AC%A1%20load%2Fstore%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>多维数组按行主序或列主序展开成一维；跨大步长会打穿<a href="/cs/locality-principle">局部性原理</a>，渐近步数仍 \\(\\Theta(1)\\) 每次访问。这正是合同里「步」与「常数」要分开的理由。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数组把字典里「已知下标」这一特例做到最优。未知键的查找仍要扫，无序时 \\(\\Theta(n)\\)。后课链表用指针换「中间插入 \\(\\Theta(1)\\)」（已有前驱时），代价是丢掉随机访问和局部性。</p><p>边界检查不是 ISA 默认：越界是安全课才会强制的，本课在合同里写前置条件，实现可以省略检查。定长构造失败只发生在分配阶段，不发生在下标算术里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入动态数组的倍增，不把切片当成独立 ADT。也不把数组写成「唯一的表」：关联查找是树与散列的缺口。NUMA 上大数组可能跨节点，地址计算仍是乘加，延迟不是 \\(O(1)\\) 纳秒。</p><p>后课默认：谈到连续表，按下标读写 \\(\\Theta(1)\\) 步；中间插入需搬移。链表用来买另一组代价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>连续布局把下标变成基址加偏移，RAM 下随机访问 \\(\\Theta(1)\\)。</li><li>中间插入 \\(\\Theta(n)\\)；顺序扫吃空间局部性。</li><li>链表用指针换插入，下一课把局部性代价说清。</li><li>倍增扩容不在本课；按下标仍假定长度已知。</li><li>出处：Knuth, <em>TAOCP</em> 卷 1；Cormen et al. 数组作为表的表示。</li></ul>',9))])}const b=s(m,[["render",p]]);export{E as __pageData,b as default};
